export interface ProgramGradesItem {
    /**
     * Grade number.
     */
    gradeNumber?: number;
    /**
     * Unique identificator for grade.
     */
    uid?: number;
    /**
     * Grade name.
     */
    name?: string;
    /**
     * Switch to enable/disable grade.
     */
    enabled?: boolean;
    /**
     * Program name.
     */
    program?: string;
}
